        Colors[0] := '00AA00'; // Green
        Colors[1] := 'FF0000'; // Red
        Colors[2] := '0033EE'; // Blue
        Colors[3] := 'FFEE00'; // Yellow
        Colors[4] := 'AA00CC'; // Violett

        Colors[5] := '0077FF'; // LightBlue
        Colors[6] := 'FFFFAA'; // Cream
        Colors[7] := 'FF66DD'; // LightViolett
        Colors[8] := '00DD00'; // LightGreen
        Colors[9] := 'FF6000'; // Orange

        H := 0.7;
        R := H * 0.725;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        D := H / sqrt(5);

        for i := 0 to 59 do begin
            x[i] := R * cos(2 * Pi / 60 * (i+3));
            y[i] := R * sin(2 * Pi / 60 * (i+3));
        end;
